struct SAM { struct St { int len, link; map<char,int> nx; }; vector<St> st; int last = 0;
  SAM() { st.push_back({0, -1, {}}); }
  void extend(char c) { int cur = st.size(); st.push_back({st[last].len + 1, 0, {}}); int p = last;
    while (p != -1 && !st[p].nx.count(c)) { st[p].nx[c] = cur; p = st[p].link; }
    if (p != -1) { int q = st[p].nx[c];
      if (st[p].len + 1 == st[q].len) st[cur].link = q;
      else { int cl = st.size(); st.push_back({st[p].len + 1, st[q].link, st[q].nx});
        while (p != -1 && st[p].nx[c] == q) { st[p].nx[c] = cl; p = st[p].link; }
        st[q].link = st[cur].link = cl; } }
    last = cur; } };
```
