// Giải A x = b mod p (p nguyên tố). a là ma trận n × (m+1) (cột cuối là b). Trả về hạng; -1 nếu vô nghiệm.
long long pw(long long a, long long e, long long p) { long long r = 1; a %= p; for (; e; e >>= 1, a = a * a % p) if (e & 1) r = r * a % p; return r; }
int gauss(vector<vector<long long>>& a, long long p) { int n = a.size(), m = a[0].size() - 1, row = 0;
  for (int col = 0; col < m && row < n; ++col) { int sel = row; while (sel < n && !a[sel][col]) ++sel; if (sel == n) continue;
    swap(a[sel], a[row]); long long inv = pw(a[row][col], p - 2, p);
    for (auto& v : a[row]) v = v * inv % p;
    for (int i = 0; i < n; ++i) if (i != row && a[i][col]) { long long f = a[i][col]; for (int j = col; j <= m; ++j) a[i][j] = ((a[i][j] - f * a[row][j]) % p + p) % p; }
    ++row; }
  for (int i = row; i < n; ++i) if (a[i][m]) return -1;
  return row; }
```
