  return html`<form onSubmit=${(e) => { e.preventDefault(); if (text.trim()) setItems([...items, text]); setText(""); }}>
    <input value=${text} onInput=${(e) => setText(e.target.value)} /><button>Thêm</button></form>
    <ul>${items.map((t, i) => html`<li key=${i}>${t}</li>`)}</ul>`; }
render(html`<${App} />`, document.getElementById("app"));
</script>
